#include <bits/stdc++.h>
using namespace std;

#define rep(i, n) for(int i = 0; i < n; ++i)

int main(void){
	int n;
	long long m,c;
	cin>>n>>m>>c;
	vector<long long>a(n);
	rep(i,n)cin>>a[i];
	sort(a.begin(),a.end());

	vector<long long>b;
	vector<int>p;
	int idx=0,nxt;
	while(idx<n){
		b.push_back(a[idx]);
		nxt=idx+1;
		while(nxt<n){
			if(a[nxt]!=a[idx])break;
			nxt++;
		}
		p.push_back(nxt-idx);
		idx=nxt;
	}

	int k=b.size();
	int r=0;
	long long cur=0, ans=0;
	rep(i,k){
		while(cur<c){
			cur+=p[r];
			r++;
			if(r>=k)r-=k;
		}
		if(i==0)ans+=(m+b[0]-b[k-1])*cur;
		else ans+=(b[i]-b[i-1])*cur;
		cur-=p[i];
	}
	cout<<ans<<endl;

	return 0;
}
